<template><div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-logo"><i></i><i></i><i></i></span><span class="brand-name">Smart <b>CRM</b><small>{{ t('brandSub') }}</small></span></div><p class="nav-label">{{ t('menu') }}</p><nav><RouterLink v-for="item in items" :key="item.path" :to="item.path" exact-active-class="router-link-exact-active" :class="{ 'router-link-exact-active': router.currentRoute.value.path === item.path || (item.path !== '/' && router.currentRoute.value.path.startsWith(item.path + '/')) }"><span class="nav-icon"><Icon :name="item.key" /></span><span>{{ t(item.key) }}</span></RouterLink></nav><div class="sidebar-footer"><div class="user-box"><div class="avatar">{{ initials }}</div><div class="user-text"><strong>{{ user?.full_name || 'User' }}</strong><small>{{ user?.role || 'Member' }}</small></div><button class="logout" :title="t('logout')" :aria-label="t('logout')" @click="logout">⎋</button></div><div class="secure-line"><span>●</span> {{ t('secure') }}</div></div></aside><main class="content"><header><div><span class="eyebrow">SMART CRM <b>/</b> {{ pageTitle }}</span><h2>{{ pageTitle }}</h2><p class="header-subtitle">{{ pageSubtitle }}</p></div><div class="header-actions"><div class="header-top-actions"><div class="language-switch"><button :class="{active:locale==='uk'}" @click="setLocale('uk')">UA</button><button :class="{active:locale==='en'}" @click="setLocale('en')">EN</button></div><div class="status-pill"><span></span> {{ t('online') }}</div></div><button v-if="isDealsPage" class="primary-btn header-add-btn" @click="openCreateDeal">{{ t('addDeal') }}</button></div></header><RouterView /></main></div></template>
<script setup>
import { ref, computed, onMounted } from 'vue'; import { useRouter } from 'vue-router'; import { getMe, token } from '../api'; import Icon from '../components/Icon.vue'; import { locale, setLocale, t } from '../i18n'
const router = useRouter(), user = ref(null), items = [{key:'dashboard',path:'/'},{key:'customers',path:'/customers'},{key:'contacts',path:'/contacts'},{key:'deals',path:'/deals'},{key:'activities',path:'/activities'}]; const detailTitles = {'Customer Details':'details','Contact Details':'contactDetails','Deal Details':'dealDetails'}; const subtitleKeys = {'Dashboard':'appSubtitle','Customers':'customersSubtitle','Customer Details':'manage','Contacts':'contactsSubtitle','Contact Details':'contactsSubtitle','Deals':'dealsSubtitle','Deal Details':'dealsSubtitle','Activities':'appSubtitle'}; const isDealsPage = computed(() => router.currentRoute.value.name === 'Deals'); const pageTitle = computed(() => { const name = router.currentRoute.value.name || 'Dashboard'; return t(detailTitles[name] || String(name).toLowerCase()) }); const pageSubtitle = computed(() => t(subtitleKeys[router.currentRoute.value.name] || 'appSubtitle')); const initials = computed(() => (user.value?.full_name || 'U').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()); onMounted(async () => { try { user.value = await getMe() } catch { token.clear(); router.push('/login') } }); function openCreateDeal(){ window.dispatchEvent(new CustomEvent('crm:open-create-deal')) } function logout(){ token.clear(); router.push('/login') }
</script>
